// A read error leaves only the key out, the other keys stay, one warning names the session and
// the key and the reason class, and no value or error text is logged.
func Test_Resolve_readErrorWarnsAndOmits(t *testing.T) {
	t.Setenv("OPENAI_API_KEY", "fake-openai-env")
	t.Setenv("DEEPGRAM_API_KEY", "fake-deepgram-env")

	store := storetest.NewMemory()
	store.GetErrByKey = map[string]error{configkeys.KeyOpenAIAPIKey: errors.New("driver: bad connection fake-dsn-fragment")}
	logs := logtest.New(t)
	id := uuid.Must(uuid.NewV4())

	r := NewKeyResolver(newTestHandler(t, &config.Config{}, store))
	got := r.Resolve(context.Background(), id, []string{configkeys.KeyOpenAIAPIKey, configkeys.KeyDeepgramAPIKey})

	if _, ok := got[configkeys.KeyOpenAIAPIKey]; ok || len(got) != 0 {
		t.Errorf("Wrong match. expect: no entry (the other key has no row and the environment is no source), got: %d entries", len(got))
	}

	var warns []*logrus.Entry
	for _, e := range logs.Entries() {
		if e.Level == logrus.WarnLevel {
			warns = append(warns, e)
		}
	}
	if len(warns) != 1 {
		t.Fatalf("Wrong match. expect: one warning, got: %s", logs.Dump())
	}
	d := warns[0].Data
	if d["reason"] != "read_error" || d["key"] != configkeys.KeyOpenAIAPIKey || d["pipecatcall_id"] != id {
		t.Errorf("Wrong match. got fields: %v", d)
	}
	logs.AssertAbsent(t, "fake-openai-env", "fake-deepgram-env", "fake-dsn-fragment")
}

// A stored value that can not be decrypted (no master key, or another one) is left out with a
// warning. The environment value is not used in its place: the environment is no source.
func Test_Resolve_undecryptableWarnsAndOmits(t *testing.T) {
	t.Setenv("OPENAI_API_KEY", "fake-openai-env")

	store := storetest.NewMemory()
	writer := newTestHandler(t, &config.Config{ConfigEncryptionKeys: testKeyList(1)}, store)
	setSecret(t, writer, configkeys.KeyOpenAIAPIKey, "fake-db-openai")

	for name, cfg := range map[string]*config.Config{
		"no master key":   {},
		"another version": {ConfigEncryptionKeys: testKeyList(2)},
	} {
		t.Run(name, func(t *testing.T) {
			logs := logtest.New(t)

			r := NewKeyResolver(newTestHandler(t, cfg, store))
			got := r.Resolve(context.Background(), uuid.Must(uuid.NewV4()), []string{configkeys.KeyOpenAIAPIKey})

			if got != nil {
				t.Errorf("Wrong match. expect: nil, got: %d entries", len(got))
			}
			found := false
			for _, e := range logs.Entries() {
				if e.Level == logrus.WarnLevel && e.Data["reason"] == "undecryptable" && e.Data["key"] == configkeys.KeyOpenAIAPIKey {
					found = true
				}
			}
			if !found {
				t.Errorf("Wrong match. expect: an undecryptable warning, got: %s", logs.Dump())
			}
			logs.AssertAbsent(t, "fake-openai-env", "fake-db-openai")
		})
	}
}

type blockingStore struct {
	confighandler.Store
	gets atomic.Int32
}

func (b *blockingStore) Get(ctx context.Context, _ string) (*confighandler.Row, error) {
	b.gets.Add(1)
	<-ctx.Done()

	return nil, ctx.Err()
}

// The bound is for all keys of a session together: after it the remaining keys are not read and
// each is reported as a timeout.
func Test_Resolve_timeout(t *testing.T) {
	store := &blockingStore{Store: storetest.NewMemory()}
	logs := logtest.New(t)

	r := NewKeyResolver(newTestHandler(t, &config.Config{}, store))
	r.timeout = 50 * time.Millisecond

	started := time.Now()
	got := r.Resolve(context.Background(), uuid.Must(uuid.NewV4()), allKeyNames())
	took := time.Since(started)

	if got != nil {
		t.Errorf("Wrong match. expect: nil, got: %d entries", len(got))
	}
	if took > 2*time.Second {
		t.Errorf("Wrong match. expect: about the bound for all keys, got: %v", took)
	}
	if n := store.gets.Load(); n != 1 {
		t.Errorf("Wrong match. expect: one read before the bound, got: %d", n)
	}

	timeouts := 0
	for _, e := range logs.Entries() {
		if e.Level == logrus.WarnLevel && e.Data["reason"] == "timeout" {
			timeouts++
		}
	}
	if timeouts != 8 {
		t.Errorf("Wrong match. expect: a timeout warning for each of the 8 keys, got: %d", timeouts)
	}
}

func Test_readTimeoutIsTwoSeconds(t *testing.T) {
	r := NewKeyResolver(newTestHandler(t, &config.Config{}, storetest.NewMemory()))
	if r.timeout != 2*time.Second {
		t.Errorf("Wrong match. expect: 2s, got: %v", r.timeout)
	}
}

type countingStore struct {
	confighandler.Store
	gets atomic.Int32
}

func (c *countingStore) Get(ctx context.Context, key string) (*confighandler.Row, error) {
	c.gets.Add(1)
	return c.Store.Get(ctx, key)
}

func Test_Resolve_dedupAndEmpty(t *testing.T) {
	store := &countingStore{Store: storetest.NewMemory()}
	r := NewKeyResolver(newTestHandler(t, &config.Config{}, store))

	if got := r.Resolve(context.Background(), uuid.Nil, nil); got != nil || store.gets.Load() != 0 {
		t.Errorf("Wrong match. expect: nil and no read, got: %v %d", got, store.gets.Load())
	}
	if got := r.Resolve(context.Background(), uuid.Nil, []string{}); got != nil || store.gets.Load() != 0 {
		t.Errorf("Wrong match. expect: nil and no read, got: %v %d", got, store.gets.Load())
	}

	r.Resolve(context.Background(), uuid.Nil, []string{configkeys.KeyXAIAPIKey, configkeys.KeyXAIAPIKey, configkeys.KeyXAIAPIKey})
	if n := store.gets.Load(); n != 1 {
		t.Errorf("Wrong match. expect: one read for a repeated name, got: %d", n)
	}
}

// Nothing is cached: a changed value is seen by the next call.
func Test_Resolve_nextCallSeesChange(t *testing.T) {
	store := storetest.NewMemory()
	h := newTestHandler(t, &config.Config{ConfigEncryptionKeys: testKeyList(1)}, store)
	r := NewKeyResolver(h)
	names := []string{configkeys.KeyCartesiaAPIKey}

	setSecret(t, h, configkeys.KeyCartesiaAPIKey, "fake-one")
	if got := r.Resolve(context.Background(), uuid.Nil, names); string(got[names[0]]) != "fake-one" {
		t.Errorf("Wrong match. expect: the first value")
	}

	setSecret(t, h, configkeys.KeyCartesiaAPIKey, "fake-two")
	if got := r.Resolve(context.Background(), uuid.Nil, names); string(got[names[0]]) != "fake-two" {
		t.Errorf("Wrong match. expect: the changed value")
	}

	if _, err := h.Clear(context.Background(), uuid.Must(uuid.NewV4()), configkeys.KeyCartesiaAPIKey); err != nil {
		t.Fatalf("Wrong match. expect: ok, got: %v", err)
	}
	if got := r.Resolve(context.Background(), uuid.Nil, names); got != nil {
		t.Errorf("Wrong match. expect: nil after clear, got: %d entries", len(got))
	}
}

// The values are redacted when printed and plain only in JSON (the request body needs the value).
func Test_Resolve_resultIsRedacted(t *testing.T) {
	store := storetest.NewMemory()
	setSecret(t, newTestHandler(t, &config.Config{ConfigEncryptionKeys: testKeyList(1)}, store), configkeys.KeyGoogleAPIKey, "fake-google-env")

	r := NewKeyResolver(newTestHandler(t, &config.Config{ConfigEncryptionKeys: testKeyList(1)}, store))
	got := r.Resolve(context.Background(), uuid.Nil, []string{configkeys.KeyGoogleAPIKey})

	typed := got
	printed := fmt.Sprintf("%v %+v %#v %s", typed, typed, typed, typed)
	if strings.Contains(printed, "fake-google-env") || !strings.Contains(printed, "<redacted>") {
		t.Errorf("Wrong match. the value was printed: %s", printed)
	}

	body, err := json.Marshal(typed)
	if err != nil || !strings.Contains(string(body), "fake-google-env") {
		t.Errorf("Wrong match. the request body needs the plain value, got: %s %v", body, err)
	}
}

// The local endpoints text is handed over as it is (no parsing, no re-encoding), at the longest
// accepted size; a longer text can not be stored.
func Test_localEndpoints_boundary(t *testing.T) {
	prefix := `{"vllm-a":{"base_url":"http://h.example.invalid:8000/v1","api_key":"`
	suffix := `"}}`
	fill := func(n int) string {
		return prefix + strings.Repeat("k", n-len(prefix)-len(suffix)) + suffix
	}

	store := storetest.NewMemory()
	h := newTestHandler(t, &config.Config{ConfigEncryptionKeys: testKeyList(1)}, store)

	longest := fill(2020)
	setSecret(t, h, configkeys.KeyLocalLLMEndpoints, longest)
	got := NewKeyResolver(h).Resolve(context.Background(), uuid.Nil, []string{configkeys.KeyLocalLLMEndpoints})
	if string(got[configkeys.KeyLocalLLMEndpoints]) != longest {
		t.Errorf("Wrong match. expect: the text unchanged at 2020 bytes")
	}

	if _, err := h.SetSecret(context.Background(), uuid.Must(uuid.NewV4()), configkeys.KeyLocalLLMEndpoints, fill(2021)); !errors.Is(err, confighandler.ErrTooLong) {
		t.Errorf("Wrong match. expect: ErrTooLong for 2021 bytes, got: %v", err)
	}
}

// A bad master key list never stops the service and is never printed.
func Test_New_badMasterKeyIsLoggedWithoutTheText(t *testing.T) {
	var buf bytes.Buffer
	logrus.SetOutput(&buf)
	defer logrus.SetOutput(logrus.StandardLogger().Out)

	h := newTestHandler(t, &config.Config{ConfigEncryptionKeys: "7:unlikely-to-appear-in-logs"}, storetest.NewMemory())

	if _, err := h.SetSecret(context.Background(), uuid.Must(uuid.NewV4()), configkeys.KeyOpenAIAPIKey, "x"); !errors.Is(err, confighandler.ErrKeyNotConfigured) {
		t.Errorf("Wrong match. expect: key not configured, got: %v", err)
	}
	if !strings.Contains(buf.String(), config.EnvConfigEncryptionKeys) {
		t.Errorf("Wrong match. expect: the problem to be logged, got: %q", buf.String())
	}
	if strings.Contains(buf.String(), "unlikely-to-appear-in-logs") {
		t.Errorf("Wrong match. the key list text was logged")
	}
}

// Without a master key list the handler is created, the environment is no source, and a secret can
// not be stored. An empty list is not reported as an error.
func Test_New_noMasterKeyStillStarts(t *testing.T) {
	t.Setenv("XAI_API_KEY", "fake-xai-env")
	logs := logtest.New(t)

	h := newTestHandler(t, &config.Config{}, storetest.NewMemory())

	got := NewKeyResolver(h).Resolve(context.Background(), uuid.Nil, []string{configkeys.KeyXAIAPIKey})
	if got != nil {
		t.Errorf("Wrong match. expect: nil (the environment is no source), got: %d entries", len(got))
	}
	if _, err := h.SetSecret(context.Background(), uuid.Must(uuid.NewV4()), configkeys.KeyXAIAPIKey, "x"); !errors.Is(err, confighandler.ErrKeyNotConfigured) {
		t.Errorf("Wrong match. expect: key not configured, got: %v", err)
	}
	if strings.Contains(logs.Dump(), config.EnvConfigEncryptionKeys) {
		t.Errorf("Wrong match. an empty master key list must not be reported: %s", logs.Dump())
	}
}

func Test_LogSources(t *testing.T) {
	t.Setenv("OPENAI_API_KEY", "env-openai-text")

	store := storetest.NewMemory()
	writer := newTestHandler(t, &config.Config{ConfigEncryptionKeys: testKeyList(1)}, store)
	setSecret(t, writer, configkeys.KeyDeepgramAPIKey, "stored-deepgram-text")

	t.Run("sources are info lines", func(t *testing.T) {
		logs := logtest.New(t)
		LogSources(context.Background(), newTestHandler(t, &config.Config{ConfigEncryptionKeys: testKeyList(1)}, store))

		sources := map[any]any{}
		for _, e := range logs.Entries() {
			if e.Level != logrus.InfoLevel {
				t.Errorf("Wrong match. expect: info lines only, got: %v %s", e.Level, e.Message)
			}
			sources[e.Data["key"]] = e.Data["source"]
		}
		if len(sources) != 8 || sources[configkeys.KeyOpenAIAPIKey] != confighandler.SourceNone ||
			sources[configkeys.KeyDeepgramAPIKey] != confighandler.SourceDB || sources[configkeys.KeyXAIAPIKey] != confighandler.SourceNone {
			t.Errorf("Wrong match. got: %v", sources)
		}
		logs.AssertAbsent(t, "env-openai-text", "stored-deepgram-text")
	})

	t.Run("undecryptable is an error", func(t *testing.T) {
		logs := logtest.New(t)
		LogSources(context.Background(), newTestHandler(t, &config.Config{}, store))

		if !strings.Contains(logs.Dump(), "The stored config value can not be used. key: deepgram.api_key") || !logs.HasLevel(logrus.ErrorLevel) {
			t.Errorf("Wrong match. expect: an error for the unusable stored value, got: %s", logs.Dump())
		}
		logs.AssertAbsent(t, "stored-deepgram-text", "env-openai-text")
	})
}

func Test_LogSources_readError(t *testing.T) {
	store := storetest.NewMemory()
	store.ListErr = errors.New("database is down")

	logs := logtest.New(t)
	LogSources(context.Background(), newTestHandler(t, &config.Config{}, store))

	if !logs.HasLevel(logrus.WarnLevel) {
		t.Errorf("Wrong match. expect: a warning, got: %s", logs.Dump())
	}
	if logs.HasLevel(logrus.ErrorLevel) || logs.HasLevel(logrus.FatalLevel) || logs.HasLevel(logrus.PanicLevel) {
		t.Errorf("Wrong match. expect: a warning only, got: %s", logs.Dump())
	}
}
